create table if not exists public.loop_titles (id uuid primary key default gen_random_uuid(), bridge_title_id text unique references public.bridge_titles(id), slug text not null unique, title text not null, synopsis text, description text, content_type text not null default 'Film', language text, year integer, duration_minutes integer, maturity_rating text, poster_path text, backdrop_path text, trailer_path text, playback_path text, metadata jsonb not null default '{}'::jsonb, status text not null default 'draft' check (status in ('draft','approved','revoked')), listed boolean not null default false, published boolean not null default false, featured boolean not null default false, access_tier text not null default 'SVOD' check (access_tier in ('FREE','SVOD','TVOD')), tvod_rental_price numeric(10,2), tvod_purchase_price numeric(10,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.loop_plans (id uuid primary key, plan_key text not null unique, name text not null, price_inr numeric(10,2) not null, duration_days integer not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.loop_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), plan_id uuid not null references public.loop_plans(id), status text not null, current_period_start timestamptz not null, current_period_end timestamptz not null, razorpay_subscription_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id));
create table if not exists public.loop_user_tvod_entitlements (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), title_id uuid not null references public.loop_titles(id), access_type text not null check (access_type in ('RENTAL','PURCHASE')), purchased_at timestamptz not null default now(), started_watching_at timestamptz, expires_at timestamptz, payment_transaction_id text not null, status text not null default 'ACTIVE', unique(user_id,title_id,access_type));
create table if not exists public.loop_payment_events (id uuid primary key default gen_random_uuid(), event_id text not null unique, event_name text not null, razorpay_payment_id text, user_id uuid references auth.users(id), status text not null default 'received', payload jsonb not null default '{}'::jsonb, received_at timestamptz not null default now(), processed_at timestamptz);
create table if not exists public.loop_watch_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), title_id uuid not null references public.loop_titles(id), position_seconds numeric(12,2) not null default 0, duration_seconds numeric(12,2) not null default 0, completed boolean not null default false, updated_at timestamptz not null default now(), unique(user_id,title_id));
create table if not exists public.bridge_loop_publications (id uuid primary key default gen_random_uuid(), bridge_title_id text not null unique references public.bridge_titles(id), loop_title_id uuid not null unique references public.loop_titles(id), authorization_status text not null default 'pending' check (authorization_status in ('pending','authorized','revoked','expired')), territories text[] not null default '{}', languages text[] not null default '{}', exploitation_models text[] not null default '{}', window_start timestamptz, window_end timestamptz, approved_by text, approved_at timestamptz, revoked_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.loop_titles enable row level security; alter table public.loop_plans enable row level security; alter table public.loop_subscriptions enable row level security; alter table public.loop_user_tvod_entitlements enable row level security; alter table public.loop_payment_events enable row level security; alter table public.loop_watch_progress enable row level security; alter table public.bridge_loop_publications enable row level security;